import{at as e,it as t,t as n,yt as r}from"./chunks/framework.ILid7KTz.js";var i=JSON.parse(`{"title":"Overview","description":"","frontmatter":{"title":"Overview"},"headers":[],"relativePath":"guides/contributing/writing-documentation/index.md","filePath":"guides/contributing/writing-documentation/index.md"}`),a={name:`guides/contributing/writing-documentation/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="writing-documentation" tabindex="-1">Writing Documentation <a class="header-anchor" href="#writing-documentation" aria-label="Permalink to “Writing Documentation”">​</a></h1><h2 id="know-your-audience" tabindex="-1">Know Your Audience <a class="header-anchor" href="#know-your-audience" aria-label="Permalink to “Know Your Audience”">​</a></h2><p><strong><em>Warp</em>Drive</strong>&#39;s documentation has to balance appealing to many different audiences:</p><ul><li><strong>Decision makers</strong>: VPs and Directors who hear about <strong><em>Warp</em>Drive</strong> at a conference and feel their team should evaluate whether it solves their business problems.</li><li><strong>Technical evaluators</strong>: Tech Leads, Senior ICs, and Architects who want to decide if it solves their tech needs.</li><li><strong>Hobbyists</strong> who heard about it and want to try it for a weekend project.</li><li><strong>New engineers</strong> who just started at a company and want to learn about this thing the company uses.</li><li><strong>Existing users</strong> who want to find the documentation for something, learn the project deeper, or need to know how to upgrade from one version to the next.</li><li><strong>LLMs and coding agents</strong> answering questions about <strong><em>Warp</em>Drive</strong> or writing code against it, whether from the published site, the TSDoc in the source, or the agent skills. They read one page at a time with no memory of the rest. The heading, naming, and self-contained-page guidelines below exist for them as much as for anyone.</li></ul><p>Default to assuming the reader either does not use <strong><em>Warp</em>Drive</strong> yet or is just getting started. The guide for each type of doc narrows that default to its own readers, but a few guidelines apply everywhere:</p><ul><li>Landing pages and introductions should entice decision makers and technical evaluators, and give hobbyists a fast path in.</li><li>Anything that teaches should start from the assumption that the reader has no context on the project&#39;s history.</li><li>Cross-link concepts whenever possible, especially when first introducing one.</li><li>Title pages and sections in the words a reader would search for or scan past. A plain noun phrase or a question beats a clever heading: it is what search engines index, what a model routes by, and what a skimming human stops on.</li><li>Use one name per concept and use it everywhere. Mark recommended, legacy, and deprecated approaches explicitly where they appear, with the <code>@recommended</code>, <code>@discouraged</code>, and <code>@deprecated</code> tags in API docs and &quot;Legacy&quot; in page titles, so a reader or model landing on an older pattern cannot mistake it for the current one. Make each page answer its own question without depending on the reader having seen a neighbor.</li><li>Content for existing users, such as upgrade guides and legacy setup, can presume some knowledge of older concepts but should never presume knowledge of newer ones, and should be kept separate from everything else so it does not muddy the path for new readers. <a href="/pr-preview/pr-11087/upgrading/">Upgrading</a> is its own top-level section and legacy pages are explicitly named, such as <a href="/pr-preview/pr-11087/guides/configuration/ember">Setup - Legacy (Ember)</a>, for exactly this reason.</li></ul><h2 id="iterate-a-lot" tabindex="-1">Iterate, A Lot <a class="header-anchor" href="#iterate-a-lot" aria-label="Permalink to “Iterate, A Lot”">​</a></h2><p>Write the documentation someone needs, ask them to use it, and fix the places where they stumble before the next person reads it. Every round of that makes the docs work for a wider audience.</p><h2 id="which-type-of-doc-should-i-write" tabindex="-1">Which Type of Doc Should I Write? <a class="header-anchor" href="#which-type-of-doc-should-i-write" aria-label="Permalink to “Which Type of Doc Should I Write?”">​</a></h2><ul><li><strong>Proposing a new public API, a behavior change, or a deprecation?</strong> Write an <strong>RFC</strong> under <code>rfcs/</code>, published at <a href="/pr-preview/pr-11087/rfcs/">/rfcs</a>. It comes before any of the docs below. See <a href="./../rfc-process">The RFC Process</a>.</li><li><strong>Documenting a function, class, type, or its params?</strong> Write <strong>API Docs</strong>: <a href="https://tsdoc.org/" target="_blank" rel="noreferrer">TSDoc</a> comments in the source next to the symbol. Published at <a href="/pr-preview/pr-11087/api/">/api</a>. See <a href="./writing-api-docs">Writing API Docs</a>.</li><li><strong>Introducing a package as a whole?</strong> Write its <strong>README</strong>, shown on GitHub and npm, and its <code>src/index.md</code> (for example <code>warp-drive-packages/core/src/index.md</code>), which is the package&#39;s landing page in the API docs. See <a href="./writing-api-docs#readmes-and-src-index-md">READMEs and <code>src/index.md</code></a>.</li><li><strong>Teaching a concept or how to accomplish a task?</strong> Write a <strong>Guide</strong> under <code>guides/</code>, compiled from markdown and published at <a href="/pr-preview/pr-11087/guides/">/guides</a>. Step-by-step walkthroughs go in the <a href="/pr-preview/pr-11087/guides/tutorials/">Tutorials</a> section (<code>guides/tutorials/</code>). See <a href="./writing-guides">Writing Guides</a>.</li><li><strong>Walking existing users through an upgrade or a deprecation?</strong> Write an <strong>Upgrading</strong> page under <code>upgrading/</code>, published at <a href="/pr-preview/pr-11087/upgrading/">/upgrading</a>.</li><li><strong>Announcing something as of a point in time?</strong> Write a <strong>Blog</strong> post under <code>blog/</code>, published at <a href="/pr-preview/pr-11087/blog/">/blog</a>. Upgrading and Blog pages both have permanent URLs; see <a href="./writing-guides#upgrading-and-blog-pages">Upgrading and Blog Pages</a>.</li><li><strong>Instructions a coding agent should follow?</strong> Write an <strong>Agent skill</strong> under <code>warp-drive-packages/memory-alpha/skills/</code>: plain markdown routed by an index, published at <a href="/pr-preview/pr-11087/skills/">/skills</a>. See <a href="./writing-agent-skills">Writing Agent Skills</a>.</li></ul><h2 id="cross-documentation-checklist" tabindex="-1">Cross-Documentation Checklist <a class="header-anchor" href="#cross-documentation-checklist" aria-label="Permalink to “Cross-Documentation Checklist”">​</a></h2><p>Most code changes affect more than one type of doc. Use this checklist to find every doc a change should touch, so a new API does not land with TSDoc but no guide, or a deprecation without an upgrade path.</p><p>New public API:</p><ul><li>An accepted RFC, if the API is new or changes behavior. See <a href="./../rfc-process">The RFC Process</a>.</li><li>TSDoc with <code>@since</code> set to the version it ships in, and a usage example.</li><li>A guide showing usage, if it is a concept users need to learn.</li><li>A mention in the package README and <code>src/index.md</code>, only if it changes the package&#39;s headline story.</li></ul><p>Breaking change or deprecation:</p><ul><li>An accepted RFC. See <a href="./../rfc-process">The RFC Process</a>.</li><li>Update the affected TSDoc, marking <code>@deprecated</code> with a link to the replacement.</li><li>Add or update the <code>upgrading/</code> guide for the version the change ships in.</li><li>Fix Guides and README examples that use the old API.</li></ul><p>Bug fix:</p><ul><li>Update TSDoc only if documented behavior changed.</li><li>Update a guide only if recommended usage changed.</li></ul><h2 id="how-the-docs-site-is-built" tabindex="-1">How the Docs Site Is Built <a class="header-anchor" href="#how-the-docs-site-is-built" aria-label="Permalink to “How the Docs Site Is Built”">​</a></h2><p>Everything on the site except the API docs is markdown copied from the repo by <code>docs-viewer/src/prepare-website.ts</code> on each build: <code>guides/</code> to <code>/guides</code>, <code>upgrading/</code> to <code>/upgrading</code>, <code>blog/</code> to <code>/blog</code>, <code>rfcs/</code> to <code>/rfcs</code>, and <code>warp-drive-packages/memory-alpha/skills/</code> to <code>/skills</code>. The API docs are generated from the source by TypeDoc into <code>/api</code>. Package READMEs are not on the site; GitHub and npm render them.</p><h3 id="sidebar-and-meta-json" tabindex="-1">Sidebar and <code>_meta.json</code> <a class="header-anchor" href="#sidebar-and-meta-json" aria-label="Permalink to “Sidebar and _meta.json”">​</a></h3><p>Each content directory&#39;s <code>_meta.json</code> controls how it appears in the sidebar:</p><ul><li><code>title</code> sets the sidebar label for the directory.</li><li><code>items</code> is the ordered list of child slugs (filenames without <code>.md</code>, or subdirectory names). Unlisted items sort alphabetically after the listed ones, so when you add a page, add its slug to <code>items</code> where it belongs.</li><li><code>files</code> holds per-file metadata keyed by filename without <code>.md</code>, such as a <code>title</code> or <code>draft</code>. A page&#39;s own frontmatter <code>title</code> wins over a <code>files</code> entry when both are set.</li><li><code>draft</code> on a <code>files</code> entry or in a page&#39;s own frontmatter hides that page from the sidebar; on the directory it hides every page in it. In <code>guides/</code>, <code>upgrading/</code>, and <code>blog/</code> a hidden page is still built and reachable at its URL. In the agent skills a <code>draft</code> page is removed from the site entirely.</li><li><code>collapsed</code> controls whether the directory&#39;s sidebar group starts collapsed.</li></ul><p>The sidebar is computed once, when VitePress loads its config. A page added while the dev server is running is served at its URL but does not appear in the sidebar until you restart the server.</p><h3 id="markdown" tabindex="-1">Markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to “Markdown”">​</a></h3><p>All <a href="https://vitepress.dev/guide/markdown" target="_blank" rel="noreferrer">VitePress markdown features</a> are available, including custom containers (<code>::: tip</code>, <code>::: warning</code>) and <a href="https://vitepress.dev/guide/markdown#code-groups" target="_blank" rel="noreferrer">code groups</a>. One consequence of VitePress compiling markdown to Vue: a bare <code>&lt;thing&gt;</code> in prose is parsed as an element and fails the build, and the link checker will not warn you first. Wrap angle brackets in single backticks.</p><h3 id="checking-links" tabindex="-1">Checking Links <a class="header-anchor" href="#checking-links" aria-label="Permalink to “Checking Links”">​</a></h3><p><code>pnpm lint:docs</code> from the repo root renders every page in the content roots above and fails on any link whose target page or <code>#anchor</code> does not exist. CI runs it. It does not cover package READMEs, and it does not catch markdown that fails to compile; only the build does.</p><h3 id="previewing-your-changes" tabindex="-1">Previewing Your Changes <a class="header-anchor" href="#previewing-your-changes" aria-label="Permalink to “Previewing Your Changes”">​</a></h3><p>Run <code>pnpm start</code> from <code>docs-viewer/</code> for a dev server with hot reload, or <code>pnpm build</code> then <code>pnpm preview</code> for the production build; details in the <a href="https://github.com/warp-drive-data/warp-drive/blob/main/docs-viewer/README.md" target="_blank" rel="noreferrer">Docs Viewer README</a>. Once the change is in a pull request, add the existing <code>:label: doc</code> label (its name literally contains <code>:label:</code>), or ask a maintainer to if you cannot edit labels on the repo, and a preview of the whole site, API docs included, is deployed to <code>https://canary.warp-drive.io/pr-preview/pr-&lt;number&gt;/</code> and linked from a comment on the PR.</p>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};